package org.circus.core;

import java.awt.image.BufferedImage;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.TimeUnit;

/** Real Windows slots -> owned portable story slots through the shipping
 * DesktopLegacy/Runtime APIs. Originals stay read-only; no dialogue is logged.
 * Optional third argument supplies DCPC for wrong-profile CLI checks. */
public final class Dc2NativeImportPlatformAudit {
    private static int checks;
    private interface Work {void run()throws Exception;}
    private static void check(boolean yes,String why){checks++;if(!yes)throw new AssertionError(why);}
    private static void reject(Work work,String why)throws Exception{boolean bad=false;try{work.run();}catch(IOException|IllegalArgumentException expected){bad=true;}check(bad,why);}
    private static int[] pixels(DesktopLegacy e)throws IOException{BufferedImage b=e.render();try{return b.getRGB(0,0,b.getWidth(),b.getHeight(),null,0,b.getWidth());}finally{b.flush();}}
    private static String pixelsHash(int[] values){byte[] b=new byte[values.length*4];for(int n=0;n<values.length;n++)for(int k=0;k<4;k++)b[n*4+k]=(byte)(values[n]>>>(k*8));return Binary.sha256(b);}
    private static byte[] preview(DesktopLegacy e)throws IOException{BufferedImage b=e.preview();try{return DesktopSave.thumbnail(b,256,192);}finally{b.flush();}}
    private static String canonical(String s){return s.replace('\\','/').toLowerCase(Locale.ROOT);}
    private static Path slot(DesktopLegacy e,int n){return e.saveDirectory.resolve("slot-"+n+".sav");}
    private static DesktopLegacy engine(CircusResources data,TextCodec codec)throws Exception{return new DesktopLegacy(data,codec,true);}
    private static void story(DesktopLegacy e)throws Exception{
        for(int n=0;n<30000;n++){
            e.tick(600000);if(e.textWaiting()&&!e.body().isEmpty()&&!e.menuWaiting())return;
            if(e.menuWaiting()){List<String> actions=new ArrayList<>();for(DesktopEngine.Control c:e.controls())actions.add(c.action);if(actions.contains("03"))e.choose("03");else if(actions.contains("start"))e.choose("start");else throw new IOException("Import audit startup menu not mapped");}
            for(int ch=0;ch<6;ch++)e.audioCompleted(ch,e.audioGeneration(ch));e.vm().signalHost(e.ticket(),MesVm.HostSignal.MEDIA_COMPLETE);e.vm().signalHost(e.ticket(),MesVm.HostSignal.TEXT_COMPLETE);
            if(e.vm().status()==MesVm.Status.WAIT_HOST&&!e.menuWaiting())e.click(e.width/2,e.height/2,false);
            if(e.vm().status()==MesVm.Status.FAULT)throw new IOException(e.vm().error());
        }throw new IOException("Import audit did not reach an active story");
    }
    private static Set<String> savedFiles(Path directory)throws IOException{Set<String> files=new TreeSet<>();if(Files.exists(directory))try(DirectoryStream<Path> stream=Files.newDirectoryStream(directory)){for(Path p:stream)if(Files.isRegularFile(p))files.add(p.getFileName().toString());}return files;}
    private static void unchanged(DesktopLegacy live,Object vm,byte[] state,int[] frame)throws IOException{check(live.vm()==vm&&Arrays.equals(state,live.snapshot()),"native conversion never replaces or mutates active VM");check(Arrays.equals(frame,pixels(live)),"native conversion leaves active pixels unchanged");}
    private static int followingWait(MesScript code,int at)throws IOException{for(int n=0;n<100;n++){MesScript.Record r=code.fetchRecord(at);if(r.opcode==7)return r.end;at=r.end;}throw new IOException("Native import audit checkpoint has no following07");}
    private static Map<String,Object> restored(CircusResources data,TextCodec codec,Dc2NativeSlot nativeSlot,Path path)throws Exception{
        DesktopSave metadata=DesktopSave.decode(Files.readAllBytes(path));check(metadata.state.length>8004&&metadata.preview.length>0&&!metadata.caption.isEmpty(),"converted slot contains portable state, preview and caption");check(metadata.icon==nativeSlot.ordinary(9,20),"converted icon retains original9:20");
        Calendar date=new GregorianCalendar();date.setTimeInMillis(metadata.created);check(date.get(Calendar.YEAR)==2000+nativeSlot.ordinary(9,25)&&date.get(Calendar.MONTH)+1==nativeSlot.ordinary(9,21)&&date.get(Calendar.DAY_OF_MONTH)==nativeSlot.ordinary(9,22)&&date.get(Calendar.HOUR_OF_DAY)==nativeSlot.ordinary(9,23)&&date.get(Calendar.MINUTE)==nativeSlot.ordinary(9,24),"converted metadata retains original slot date");
        for(long position:metadata.position)check(position==0,"native import has no physical cursor and requests zero restart");
        DesktopLegacy loaded=engine(data,codec);loaded.restore(path);MesScript code=data.scripts().script(nativeSlot.scriptName());Dc2NativeSlot.Plan plan=nativeSlot.normalTextPlan(code);
        check(loaded.vm().scriptName().equals(plan.script)&&loaded.vm().offset()==followingWait(code,plan.resumeFilePc),"converted VM replays the actual checkpoint to following07");check(loaded.textWaiting()&&!loaded.body().isEmpty()&&!loaded.session.inSystem(),"converted slot restores an ordinary text wait");
        byte[] ordinary=nativeSlot.ordinaryBytes();for(int n=0;n<ordinary.length;n++)check(loaded.vm().variables.read(n/100,n%100)==(ordinary[n]&255),"converted ordinary byte "+n);
        Dc2NativeSlot.StringField[] fields={Dc2NativeSlot.StringField.BACKGROUND,Dc2NativeSlot.StringField.ACTOR1,Dc2NativeSlot.StringField.ACTOR2,Dc2NativeSlot.StringField.OVERLAY1,Dc2NativeSlot.StringField.OVERLAY2,Dc2NativeSlot.StringField.RESOURCE3,Dc2NativeSlot.StringField.RESOURCE4,Dc2NativeSlot.StringField.RESOURCE5};int[] target={1,2,3,6,7,10,11,12};
        for(int n=0;n<fields.length;n++)check(canonical(loaded.host().scene.shown.slots[target[n]]).equals(canonical(nativeSlot.resource(fields[n]))),"converted resource "+fields[n]);
        check(loaded.host().scene.backgroundX()==nativeSlot.dword(Dc2NativeSlot.Dword.BACKGROUND_X)&&loaded.host().scene.backgroundY()==nativeSlot.dword(Dc2NativeSlot.Dword.BACKGROUND_Y),"converted background coordinates");
        check(Arrays.equals(metadata.preview,preview(loaded)),"new slot preview exactly describes restored scene");check(metadata.caption.equals(loaded.saveCaption()),"new slot caption describes restored story");
        int music=nativeSlot.dword(Dc2NativeSlot.Dword.LOGICAL_MUSIC);if(music>=0)check(canonical(loaded.audio(0)).equals(canonical(data.named("music",music))),"restored original BGM name");
        int[] before=pixels(loaded);byte[] snapshot=loaded.snapshot();DesktopLegacy copy=engine(data,codec);copy.restore(snapshot);check(Arrays.equals(snapshot,copy.snapshot())&&Arrays.equals(before,pixels(copy)),"converted session saves/restores exact current state and pixels");
        int offset=loaded.vm().offset();String script=loaded.vm().scriptName();loaded.vm().signalHost(loaded.ticket(),MesVm.HostSignal.TEXT_COMPLETE);loaded.vm().signalHost(loaded.ticket(),MesVm.HostSignal.ADVANCE);loaded.tick(0);check(loaded.vm().status()!=MesVm.Status.FAULT&&(loaded.vm().offset()!=offset||!loaded.vm().scriptName().equals(script)),"converted story can advance beyond imported line");
        return Json.obj("script",plan.script,"checkpoint",plan.checkpointIndex,"checkpoint_file_pc",plan.resumeFilePc,"restored_file_pc",offset,"caption_sha256",Binary.sha256(metadata.caption.getBytes("UTF-8")),"frame_sha256",pixelsHash(before),"preview_sha256",Binary.sha256(metadata.preview),"portable_slot_bytes",Files.size(path),"advance_succeeded",true);
    }
    private static void originalMenu(DesktopLegacy e)throws Exception{
        for(int n=0;n<300;n++){e.tick(600000);if(e.menuWaiting())return;for(int ch=0;ch<6;ch++)e.audioCompleted(ch,e.audioGeneration(ch));}throw new IOException("Native import audit did not reach original LOAD menu");
    }
    private static void mouse(DesktopLegacy e,String action)throws Exception{
        for(DesktopEngine.Control c:e.controls())if(c.action.equals(action)){check(c.right>c.left&&c.bottom>c.top&&c.left>=0&&c.top>=0&&c.right<=e.width&&c.bottom<=e.height,"original LOAD action has a visible hit rectangle");e.click((c.left+c.right)/2,(c.top+c.bottom)/2,false);return;}throw new IOException("Original LOAD action missing: "+action);
    }
    private static List<Object> originalLoadUi(CircusResources data,TextCodec codec,Path base)throws Exception{
        DesktopLegacy e=engine(data,codec);e.restore(base);e.session.openSystem("LOAD",1);originalMenu(e);List<Object> pages=new ArrayList<>();
        for(int page=0;page<10;page++){check(e.host().read(99,0)==page&&e.host().grid.size()==5,"original LOAD owns ten pages of five visible cells");int[] bindings=new int[5];for(int n=0;n<5;n++){Dc2Ui.Button b=e.host().grid.get(n);bindings[n]=b.binding;check(b.binding==page*8+n&&b.right>b.left&&b.bottom>b.top&&b.left>=0&&b.top>=0&&b.right<=e.width&&b.bottom<=e.height,"original LOAD grid binding and on-screen rectangle");}pages.add(Json.obj("page",page,"bindings",bindings));mouse(e,"next1");originalMenu(e);}check(e.host().read(99,0)==0,"original LOAD next wraps last page9 to0");
        for(int target:new int[]{8,9}){e.restore(base);e.session.openSystem("LOAD",1);originalMenu(e);mouse(e,"next1");originalMenu(e);final int[] requested={-1};e.vm().boundaryListener(()->{if(e.host().loadRequest>=0)requested[0]=e.host().loadRequest;});mouse(e,"@slot:"+(target-8));originalMenu(e);mouse(e,"doload");for(int n=0;n<300&&!e.textWaiting();n++){e.tick(600000);for(int ch=0;ch<6;ch++)e.audioCompleted(ch,e.audioGeneration(ch));}check(requested[0]==target&&!e.session.inSystem()&&e.textWaiting(),"original LOAD mouse + doload restores requested visible imported slot");DesktopLegacy expected=engine(data,codec);expected.restore(slot(e,target));check(e.vm().scriptName().equals(expected.vm().scriptName())&&e.vm().offset()==expected.vm().offset()&&e.body().equals(expected.body()),"original LOAD restores imported script, exact cursor and text");e.hover(-1,-1);check(Arrays.equals(pixels(e),pixels(expected)),"original LOAD restores imported scene pixels");e.vm().boundaryListener(null);}
        return pages;
    }
    private static int cli(Path game,String executable,Path nativeFile,Path saveRoot,Integer target,Path log,boolean success)throws Exception{
        List<String> command=new ArrayList<>();command.add(Paths.get(System.getProperty("java.home"),"bin",System.getProperty("os.name").startsWith("Windows")?"java.exe":"java").toString());Collections.addAll(command,"-Xmx192m","-Dfile.encoding=UTF-8","-Dstdout.encoding=UTF-8","-Dstderr.encoding=UTF-8","-Djava.awt.headless=true","-Ddc.saveRoot="+saveRoot,"-Ddc.cacheRoot="+saveRoot.resolve("cache"),"-cp",System.getProperty("java.class.path"),"org.circus.core.DesktopRuntime",game.toString(),"--exe",executable,"--import-native-slot",nativeFile.toString());if(target!=null){command.add("--slot");command.add(target.toString());}
        Process child=new ProcessBuilder(command).redirectErrorStream(true).redirectOutput(log.toFile()).start();if(!child.waitFor(120,TimeUnit.SECONDS)){child.destroyForcibly();throw new IOException("Native import CLI timed out");}int result=child.exitValue();check(success?result==0:result!=0,"shipping CLI import expected result");return result;
    }
    public static void main(String[] args)throws Exception{
        if(args.length<2||args.length>3)throw new IOException("Require readonly_DC2_GAME owned_OUTPUT [readonly_DCPC_GAME]");Path game=Paths.get(args[0]).toRealPath(),out=DesktopRouteAudit.outputOutsideGame(game,args[1]);Path run=out.resolve("run-"+UUID.randomUUID());Files.createDirectories(run);System.setProperty("dc.saveRoot",run.resolve("direct-saves").toString());
        GameResources files=new GameResources(new LocalGameStorage(game),"dc2.exe");CircusResources data=new CircusResources(files,Profiles.get("dc2-3363"));TextCodec codec=GameText.detect(files,data.profile);DesktopLegacy live=engine(data,codec);story(live);Object owner=live.vm();byte[] active=live.snapshot();int[] visible=pixels(live);check(live.nextImportSlot()==2,"imports begin in unused ordinary slot2");
        List<Path> originals=new ArrayList<>();try(DirectoryStream<Path> stream=Files.newDirectoryStream(game.resolve("AdvData/SaveData"))){for(Path p:stream)if(Files.isRegularFile(p)&&p.getFileName().toString().matches("(?i)dc2[0-9]+\\.dat")){if(!p.toRealPath().startsWith(game))throw new IOException("Original slot outside selected game");originals.add(p);}}Collections.sort(originals);check(originals.size()==5,"current real sample has five Windows story slots");Map<Path,String> hashes=new LinkedHashMap<>();List<Object> results=new ArrayList<>();int[] destinations={2,3,4,8,9};int ordinal=0;
        for(Path original:originals){byte[] bytes=Files.readAllBytes(original);hashes.put(original,Binary.sha256(bytes));Dc2NativeSlot nativeSlot=Dc2NativeSlot.parse(bytes);int id=destinations[ordinal++];int selected=live.nextImportSlot();check(selected==id,"next import slot avoids all prior conversions");Path converted=live.importNativeSlot(bytes,selected);check(converted.equals(slot(live,id))&&Files.isRegularFile(converted),"public platform API creates requested runtime slot");check(live.host().availableSaves.contains(id)&&live.metadata(converted)!=null&&live.thumbnails.containsKey(id),"converted slot appears in original load UI metadata/preview");unchanged(live,owner,active,visible);results.add(restored(data,codec,nativeSlot,converted));}
        check(live.nextImportSlot()==10,"five imports occupy visible2,3,4,8,9 without hidden5..7");Path first=slot(live,2);byte[] firstBytes=Files.readAllBytes(first);DesktopSave cached=live.metadata(first);BufferedImage thumbnail=live.thumbnails.get(2);Set<String> prior=savedFiles(live.saveDirectory);byte[] valid=Files.readAllBytes(originals.get(0));
        reject(()->live.importNativeSlot(valid,2),"existing runtime target refuses overwrite");check(Arrays.equals(firstBytes,Files.readAllBytes(first))&&live.metadata(first)==cached&&live.thumbnails.get(2)==thumbnail,"failed overwrite preserves file, metadata cache and thumbnail");unchanged(live,owner,active,visible);
        for(int badId:new int[]{0,1,-1,5,6,7,77,80,255,256})reject(()->live.importNativeSlot(valid,badId),"reserved/out-of-range destination refused");
        List<byte[]> badInputs=new ArrayList<>();badInputs.add(new byte[8003]);badInputs.add(new byte[8004]);for(int field:new int[]{0x490,0x498,0x1f24,0x115c}){byte[] b=valid.clone();int value=field==0x490?Integer.MAX_VALUE:field==0x498?9:1;for(int n=0;n<4;n++)b[field+n]=(byte)(value>>>(8*n));badInputs.add(b);}byte[] missing=valid.clone();Arrays.fill(missing,0x84,0x104,(byte)0);byte[] name="BG/definitely_missing_native_import".getBytes(Binary.SJIS);System.arraycopy(name,0,missing,0x84,name.length);badInputs.add(missing);
        for(byte[] malformed:badInputs){reject(()->live.importNativeSlot(malformed,10),"malformed/unsupported/resource-missing native input refused");check(!Files.exists(slot(live,10))&&savedFiles(live.saveDirectory).equals(prior),"failed conversion creates no slot or temporary file");unchanged(live,owner,active,visible);}
        List<Object> nativeLoadUi=originalLoadUi(data,codec,slot(live,2));Path cliRoot=run.resolve("cli-saves"),cliDirectory=cliRoot.resolve(data.profileId+"-"+DesktopEngine.mesIdentity(data));cli(game,"dc2.exe",originals.get(0),cliRoot,12,run.resolve("cli-explicit.log"),true);Path cliSlot=cliDirectory.resolve("slot-12.sav");check(Files.isRegularFile(cliSlot),"shipping CLI writes explicit ordinary slot");byte[] old=Files.readAllBytes(cliSlot);cli(game,"dc2.exe",originals.get(1),cliRoot,12,run.resolve("cli-existing.log"),false);check(Arrays.equals(old,Files.readAllBytes(cliSlot)),"shipping CLI collision keeps old slot bytes");
        cli(game,"dc2.exe",originals.get(1),cliRoot,null,run.resolve("cli-auto.log"),true);check(Files.isRegularFile(cliDirectory.resolve("slot-2.sav")),"shipping CLI automatic selection uses unused slot2");
        for(int n:new int[]{12,2}){DesktopLegacy consumed=engine(data,codec);consumed.restore(cliDirectory.resolve("slot-"+n+".sav"));check(consumed.textWaiting()&&!consumed.body().isEmpty()&&!consumed.session.inSystem(),"shipping CLI output loads into playable ordinary text");}
        cli(game,"dc2.exe",originals.get(0),cliRoot,5,run.resolve("cli-hidden.log"),false);check(!Files.exists(cliDirectory.resolve("slot-5.sav")),"shipping CLI rejects a hidden original-LOAD destination");Path malformed=run.resolve("malformed-original.dat");Files.write(malformed,new byte[8004]);cli(game,"dc2.exe",malformed,cliRoot,11,run.resolve("cli-invalid.log"),false);check(!Files.exists(cliDirectory.resolve("slot-11.sav"))&&Arrays.equals(old,Files.readAllBytes(cliSlot)),"shipping CLI bad native input writes no target");
        boolean wrongProfile=false;if(args.length==3){Path other=Paths.get(args[2]).toRealPath(),wrong=run.resolve("wrong-profile-saves");cli(other,"DCPCDVD_CHS.exe",originals.get(0),wrong,11,run.resolve("cli-wrong-profile.log"),false);check(new String(Files.readAllBytes(run.resolve("cli-wrong-profile.log")),"UTF-8").contains("当前仅支持"),"wrong-profile failure comes from native-import profile guard");try(java.util.stream.Stream<Path> stream=Files.walk(wrong)){check(stream.noneMatch(p->p.getFileName().toString().matches("slot-[0-9]+\\.sav")),"wrong-profile CLI creates no story slot");}wrongProfile=true;}
        for(Map.Entry<Path,String> original:hashes.entrySet())check(original.getValue().equals(Binary.sha256(Files.readAllBytes(original.getKey()))),"original Windows story file unchanged");
        Files.write(out.resolve("result.json"),(Json.text(Json.obj("pass",true,"checks",checks,"actual_windows_slots",originals.size(),"converted",results,"runtime_slots",destinations,"original_load_ui",nativeLoadUi,"original_load_pages",10,"visible_importable_slots",48,"hidden_or_reserved_destinations_rejected",10,"active_vm_and_pixels_unchanged",true,"existing_target_and_caches_preserved",true,"malformed_inputs_rejected",badInputs.size(),"cli_explicit_auto_collision_invalid",true,"cli_wrong_profile_checked",wrongProfile,"original_files_sha256_unchanged",true,"owned_run_directory",run.toString(),"original_exe_executed",false,"original_game_directory_written",false,"scope","Real five Windows ordinary-text slots converted by shipping platform/CLI into original-LOAD-visible2,3,4,8,9, loaded/advanced, and portable pixels checked. Original LOAD has10 pages of5 visible cells with stride8; hidden5..7 and slots77+ are refused. Visible8/9 restored by actual grid mouse hit and original doload button. Prior native backlog, NVL/choice/pending-batch slots and physical media positions remain outside import scope."))+"\n").getBytes("UTF-8"));System.out.println("Dc2NativeImportPlatformAudit PASS "+checks+"; five real Windows slots + shipping import CLI");
    }
}
